B.Ic=s(["K\xfc\xe7\xfck \xe7ocuk parkta oynuyordu.","Bu kitab\u0131 d\xfcn ald\u0131m.","\xdc\xe7 \xf6\u011frenci s\u0131n\u0131fa girdi.","K\u0131rm\u0131z\u0131 elbisesini giymi\u015f.","Ya\u015fl\u0131 kad\u0131n bankta dinleniyordu.","Hangi otob\xfcse binece\u011fiz?","Uzun bir yolculuk bizi bekliyordu.","Birka\xe7 dergiyi masaya koydu.","Yorgun i\u015f\xe7iler servise bindi.","\u015eu kutuyu rafa kald\u0131r\u0131r m\u0131s\u0131n?"],t.s)
B.YH=s(["Yava\u015f yava\u015f merdivenleri \xe7\u0131kt\u0131.","D\xfcn ak\u015fam bize u\u011frad\u0131.","Kap\u0131y\u0131 a\xe7\u0131p i\xe7eri girdi.","Bug\xfcn \xe7ok yoruldum.","Sabahleyin erkenden yola koyuldu.","Yukar\u0131 \xe7\u0131k\u0131p perdeleri a\xe7t\u0131.","Konuyu gayet a\xe7\u0131k anlatt\u0131.","Az \xf6nce buradan ge\xe7tiler.","Biraz daha bekleyelim.","D\u0131\u015far\u0131 \xe7\u0131k\u0131p temiz hava ald\u0131."],t.s)
B.O7=s(["Buz gibi bir su i\xe7tik.","Senin i\xe7in buraya geldim.","Aslan kadar g\xfc\xe7l\xfcyd\xfc.","Bize g\xf6re sorun yok.","Kalemle yazmay\u0131 tercih ederim.","Ak\u015fama do\u011fru hava serinledi.","Sabaha kar\u015f\u0131 ya\u011fmur ba\u015flad\u0131.","Onun gibi d\xfc\u015f\xfcnm\xfcyorum.","\xd6devi bitirmek \xfczere masaya oturdu.","Bu haber herkese kar\u015f\u0131 sorumluluk y\xfckler."],t.s)
B.ZL=s(["Ali ve Ay\u015fe birlikte geldi.","Arad\u0131 ama bulamad\u0131.","Gelemedi \xe7\xfcnk\xfc hastayd\u0131.","Hem g\xfcld\xfc hem a\u011flad\u0131.","Ya bug\xfcn ya yar\u0131n u\u011frar\u0131m.","Denedi fakat ba\u015faramad\u0131.","Ders \xe7al\u0131\u015ft\u0131, \xfcstelik hi\xe7 ara vermedi.","Ne yedi ne i\xe7ti.","Kitab\u0131 okudum, oysa hi\xe7 be\u011fenmedim.","Ge\xe7 kald\u0131, dolay\u0131s\u0131yla s\u0131nava giremedi."],t.s)
B.a_Z=s(["Bunu daha \xf6nce g\xf6rm\xfc\u015ft\xfcm.","Herkes salona ge\xe7ti.","Sen bize gelir misin?","Kitab\u0131 ona verdim.","Birka\xe7\u0131 s\u0131navda ba\u015far\u0131l\u0131 olmu\u015f.","Kim arad\u0131 acaba?","\u015eunu bana uzat\u0131r m\u0131s\u0131n?","Hepsi bah\xe7ede topland\u0131.","Biz yar\u0131n erken \xe7\u0131kaca\u011f\u0131z.","Kimse kap\u0131y\u0131 a\xe7mad\u0131."],t.s)
B.Kg=s(["Eyvah, otob\xfcs\xfc ka\xe7\u0131rd\u0131k!","Aman, dikkatli ol!","Hey, buraya bak!","Yaz\u0131k, \xe7ok ge\xe7 kald\u0131k!","Aa, seni burada g\xf6rmeyi beklemiyordum!","Of, bu s\u0131cak dayan\u0131lmaz!","Bravo, ger\xe7ekten \xe7ok iyi i\u015f \xe7\u0131kard\u0131n!","Hah, sonunda bulabildim!","Vah vah, \xe7ok \xfcz\xfcld\xfcm buna!","Hadi, ge\xe7 kal\u0131yoruz!"],t.s)
